var c = color(0);

var g = [];

function setup() {
  createCanvas(windowWidth, windowHeight);
	//createCanvas(101, 101)
  reset();
}

function reset()  {
  g = new Array(width)[height];
  background(255);
  g[1][1] = 1;
  g[g.length-2][g[0].length-2] = 1;
  f = 1;
}

function mouseClicked()  {
  reset();
}
var r = 1;
var f;
var all;
function draw() {
  r++;
  all = true;
  for (let y = 1; y<g[0].length-1; y++) {
    for (let x = 1; x<g.length-1; x++) {

      if (g[x][y]==0) {
        let n = 0;
        if (g[x+1][y]==1*f) n++;
        if (g[x][y+1]==1*f) n++;
        if (g[x-1][y]==1*f) n++;
        if (g[x][y-1]==1*f) n++;
        if (n==1) {
          g[x][y] = -2;
          all = false;
        } else if (n!=0) {
          g[x][y] = -1;
          set(x, y, color(128));
        }
      }
    }
  }
  if(all)  {
    f = -1;
  }
  for (let y = 1; y<g[0].length-1; y++) {
    for (let x = 1; x<g.length-1; x++) {
      if (g[x][y] == -2) {
        g[x][y] = 1;
        randomSeed(r*100);
        set(x, y, color(random(255), random(255), random(255)));
      }
    }
  }
}
